// ─────────────────────────────────────────────────────────────────────────────
// OSCE Station Notes — substantive per-case teaching content (anamnesis,
// physical exam, diagnostic criteria, management) to accompany the OSCE Case
// Bank's frequency list. Written and verified against standard clinical
// teaching (SKDI 4A competency expectations, standard neurology/internal
// medicine/OB-GYN references) — not verbatim from any single source. Being
// filled in system by system; a case with no entry here still appears in the
// Case Bank with just its frequency tag until its notes are added.
//
// Keyed by the exact `name` string used in `osceCaseBank.ts`'s OSCE_CASES.
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Catatan satu stasiun OSCE.
 *
 * LIMA MEDAN TAMBAHAN, SEMUANYA OPSIONAL. Bentuk semula hanya memuat anamnesis,
 * pemeriksaan fisik, kriteria diagnosis, dan tatalaksana. Alat pemeriksa
 * kelengkapan menilai catatan terhadap delapan medan, sehingga SELURUH stasiun
 * di berkas ini terbaca "3/8" — bukan karena isinya kurang, melainkan karena
 * bentuknya memang tidak pernah punya medan itu. Angka 114 "belum lengkap" pada
 * daftar kerja sebagian besar berasal dari sini.
 *
 * Yang lima itu — definisi, etiologi, patofisiologi, penunjang, dan diagnosis
 * banding — memang yang ditanya penguji sesudah pemeriksaan, jadi menambahkannya
 * bukan sekadar mengejar angka. Dibuat opsional supaya stasiun yang belum diisi
 * tidak perlu diisi asal-asalan hanya agar hitungannya penuh.
 */
export interface OsceStationNote {
  definisi?: string
  etiologi?: string[]
  patofisiologi?: string
  /**
   * Patofisiologi sebagai RANTAI LANGKAH BERPANAH, bukan paragraf.
   *
   * Ditambahkan karena paragraf sepanjang sepuluh baris — sebaik apa pun
   * susunannya — harus dibaca ulang dari awal setiap kali satu mata rantai
   * terlupa, sedangkan yang dihadapi pembacanya adalah hafalan untuk ujian
   * lisan. Rantai dapat diucapkan keras-keras dan diperiksa sendiri satu per
   * satu.
   *
   * Paragrafnya TIDAK dihapus bila keduanya ada: rantai untuk menghafal,
   * paragraf untuk mengerti, dan keduanya dibutuhkan orang yang sama pada
   * waktu yang berbeda. Ruas ber-HURUF BESAR ditonjolkan; baris kosong ''
   * memisahkan dua rantai.
   */
  rantai?: string[]
  anamnesis: string[]
  pemeriksaanFisik: string[]
  penunjang?: string[]
  kriteriaDiagnosis: string
  diagnosisBanding?: string[]
  tatalaksana: string[]
  tips?: string
}

