    patofisiologi: 'Glukosa memasuki saraf tanpa memerlukan insulin, melalui GLUT-3 — dan justru itulah sebabnya sel saraf tidak terlindung ketika gula darah tinggi: ia tidak dapat menolak masuknya. Kelebihan glukosa dialirkan ke JALUR POLIOL, tempat aldose reduktase mengubahnya menjadi sorbitol dengan memakai NADPH. Dua kerugian terjadi sekaligus: sorbitol tertimbun di dalam sel dan menarik air, sedangkan NADPH yang terpakai adalah bahan yang sama yang dibutuhkan untuk memulihkan glutation — sehingga pertahanan sel terhadap radikal bebas melemah persis ketika beban radikalnya meningkat. Bersamaan dengan itu terbentuk produk glikasi lanjut (AGE) yang mengeraskan protein struktural saraf dan dinding vasa nervorum, serta jalur protein kinase C yang menyempitkan pembuluh halus itu. Saraf pun mengalami dua serangan sekaligus: keracunan metabolik dari dalam dan ISKEMIA dari luar. Serabut yang paling panjang menderita paling dahulu, sebab ia yang aliran aksonalnya paling jauh dan cadangannya paling tipis — dan karena serabut terpanjang tubuh adalah yang menuju ujung jari kaki, gejalanya bermula di kaki lalu naik. Ketika kerusakan di tungkai sudah mencapai setinggi lutut, panjang serabut yang menuju ujung jari tangan baru setara, dan saat itulah tangan mulai terkena — inilah asal pola KAUS KAKI DAN SARUNG TANGAN, yang bukan kebetulan melainkan akibat langsung dari panjang serabut. Serabut kecil tak bermielin (nyeri dan suhu) rusak lebih dahulu sehingga tahap awal terasa terbakar dan kesemutan; serabut besar bermielin (raba, getar, propriosepsi) menyusul sehingga timbul mati rasa dan langkah yang tidak mantap. Hilangnya sensasi protektif inilah yang membahayakan: luka kecil tidak terasa, tekanan berlanjut, dan bersama neuropati otonom yang membuat kulit kering serta pecah, terbentuklah ulkus kaki diabetik.',
