      'Schwannoma vestibular — tuli sesisi progresif dengan gangguan keseimbangan ringan; MRI membedakannya',
      'Migren vestibular — riwayat migren, sering disertai fotofobia dan fonofobia',
      'Stroke serebelum — vertigo dengan defisit neurologis lain, nistagmus arah berubah, ataksia berat; HINTS membantu membedakan',
