    kriteriaDiagnosis: 'PPDGJ-III/ICD-10 F41.1: kecemasan menyeluruh yang berlangsung hampir setiap hari selama beberapa minggu sampai beberapa bulan, tidak terbatas pada keadaan tertentu (free-floating), memuat unsur kekhawatiran, ketegangan motorik (gemetar, tidak dapat santai, nyeri kepala tegang), dan aktivitas otonom berlebih (berdebar, berkeringat, mulut kering, pusing). DSM-5 memakai patokan >=6 bulan dengan minimal 3 gejala somatik — perbedaan patokan ini disebutkan karena keduanya beredar di soal.',
