      'PSIKOSIS PASCAPERSALINAN atau niat bunuh diri atau niat menyakiti bayi: KEGAWATAN JIWA. Jangan tinggalkan sendirian, pastikan ada yang menjaga bayi, rujuk untuk rawat inap hari itu juga',
      'BABY BLUES: tidak diberi obat. Yakinkan bahwa ini terjadi pada sebagian besar ibu dan akan mereda sendiri; atur agar ibu dapat tidur, bagi tugas malam dengan pasangan atau keluarga, dan jadwalkan penilaian ulang dalam 2 minggu. Bila belum reda setelah 2 minggu, nilai ulang sebagai depresi',
