      'Alternatif yang aman saat menyusui: Paroksetin 10-20 mg/hari. HINDARI Fluoksetin sebagai pilihan pertama karena waktu paruhnya panjang dan menumpuk pada bayi',
      'Jelaskan bahwa antidepresan baru terasa setelah 2-4 minggu dan diteruskan minimal 6-12 bulan setelah membaik — berhenti begitu merasa lebih baik adalah sebab kekambuhan yang paling sering',
      'JANGAN memberi antidepresan tunggal sebelum menyingkirkan riwayat gangguan bipolar — dapat mencetuskan mania',
      'TIDAK PERLU MENGHENTIKAN MENYUSUI untuk memberi sertralin. Menghentikan ASI justru menambah rasa bersalah dan memperburuk depresi. Bila ibu memilih berhenti, hormati pilihannya tanpa menghakimi',
      'Pastikan ibu memperoleh tidur berkesinambungan minimal 4-5 jam sekali dalam sehari — ini resep yang sama pentingnya dengan obat; libatkan pasangan dan keluarga secara nyata dengan pembagian tugas yang jelas, bukan sekadar imbauan',
