      'Keratitis dan ulkus kornea — nyeri, silau, ada kerusakan kornea yang menyerap fluoresein',
      'Endoftalmitis — riwayat operasi atau trauma tembus, hipopion, sangat cepat memburuk',
      'MIGRAIN atau nyeri kepala klaster — nyeri kepala dengan mual dan muntah; matanya TIDAK keras dan tajam penglihatan tidak turun',
      'Perut akut — dugaan yang paling sering menyesatkan, karena mual muntahnya begitu menonjol. Periksa matanya',
      'Glaukoma neovaskular dan glaukoma fakolitik',
      'Skleritis — nyeri tumpul dalam yang mengganggu tidur, pembuluh dalam melebar dan tidak memucat dengan fenilefrin',
