    patofisiologi: 'Air mata dihasilkan kelenjar lakrimal di sudut ATAS LUAR orbita, menyapu permukaan bola mata, lalu dikumpulkan di sudut DALAM melalui punctum, kanalikuli, sakus lakrimal, dan akhirnya duktus nasolakrimalis yang bermuara ke meatus inferior hidung — itulah sebabnya orang menangis menjadi beringus. Seluruh perbedaan kedua penyakit ini mengikuti anatomi tersebut, dan letak bengkaknya sudah menegakkan diagnosis sebelum pemeriksaan apa pun. Pada DAKRIOADENITIS, yang meradang adalah kelenjarnya sendiri di fossa lakrimalis: kelenjar membesar dan mendorong kelopak atas dari sisi luar sehingga tepinya melengkung membentuk huruf S TERBALIK — tanda yang praktis khas. Karena kelenjar terletak di bagian anterolateral orbita, prosesnya berada di luar jalur pembuangan air mata dan TIDAK menimbulkan mata berair yang meluber. Pada DAKRIOSISTITIS urutannya terbalik: yang mula-mula terjadi bukan infeksi melainkan SUMBATAN. Duktus nasolakrimalis tersumbat, air mata tertahan di dalam sakus, dan sakus berubah menjadi kantong tertutup berisi cairan hangat yang tidak mengalir — keadaan yang sempurna bagi kuman untuk berkembang biak. Karena itu tanda pertamanya adalah EPIFORA, mata berair terus-menerus, yang mendahului peradangan berminggu-minggu sampai bertahun-tahun; barulah kemudian sakus terinfeksi, membengkak di bawah tendon kantus medial, dan menekan sakus mengeluarkan nanah lewat punctum — tanda pemeriksaan yang menentukan. Dari sinilah dua akibat penting: pertama, antibiotik saja tidak menyembuhkan secara tuntas selama sumbatannya tidak dibuka, sehingga kekambuhan hampir pasti; kedua, karena sakus terletak di depan septum orbita, infeksinya biasanya tinggal preseptal — tetapi bila menembus ke belakang septum ia menjadi selulitis orbita yang mengancam penglihatan dan nyawa.',
