    patofisiologi: 'Semuanya bermula dari isi mulut yang MASUK KE JALAN NAPAS pada orang yang untuk sementara kehilangan penjaganya. Refleks batuk dan penutupan glotis biasanya menolak apa pun selain udara; saat kesadaran menurun, penjaga itu lumpuh dan bahan orofaring — yang pada mulut berpenyakit periodontal memuat sampai 10^11 kuman anaerob per mililiter — turun mengikuti GAYA BERAT. Karena itulah letak abses dapat diramalkan dari posisi tubuh saat teraspirasi: segmen posterior lobus atas dan segmen superior lobus bawah pada orang yang terlentang, dan lebih sering di paru KANAN karena bronkus utama kanan lebih lebar, lebih pendek, dan lebih tegak. Dalam 7-14 hari pertama terjadi pneumonitis biasa; bila muatan kuman tidak tertangani, enzim proteolitik neutrofil mencairkan jaringan paru dan terbentuk nekrosis di tengahnya. Anaerob tumbuh subur justru karena jaringan nekrotik itu miskin oksigen — infeksinya menciptakan sendiri lingkungan yang menguntungkannya. Begitu rongga nanah menembus bronkus, isinya dibatukkan keluar: sejak saat itu sputumnya BERBAU BUSUK — bau yang berasal dari asam lemak rantai pendek hasil metabolisme anaerob, dan yang praktis memastikan diagnosis — dan udara masuk menggantikannya sehingga terbentuk batas cairan-udara yang khas pada foto toraks.',
