    patofisiologi: 'Seluruh perjalanan penyakitnya adalah kisah SATU SALURAN BUNTU YANG TERSUMBAT, dan urutan gejalanya mengikuti urutan itu dengan setia — inilah sebabnya anamnesis appendisitis begitu khas. Setelah lumen tersumbat, mukosa tetap mengeluarkan lendir sekitar 1-2 mL sehari ke dalam rongga yang isinya hanya 0,1 mL, sehingga tekanan di dalamnya naik cepat. Peregangan dinding merangsang serabut nyeri VISERAL yang berjalan bersama saraf simpatis dan masuk medula spinalis setinggi T10 — dan karena serabut viseral tidak membawa keterangan letak, otak menafsirkannya sebagai nyeri tumpul di dermatom T10, yaitu SEKITAR PUSAR. Itulah nyeri jam-jam pertama: samar, di tengah, sulit ditunjuk dengan satu jari, disertai mual dan hilang nafsu makan karena refleks viseral yang sama. Tekanan yang terus naik melampaui tekanan vena lalu tekanan arteriol; dinding menjadi iskemik, kuman menembusnya, dan peradangan mencapai PERITONEUM PARIETAL yang menyelimuti apendiks. Peritoneum parietal dipersarafi saraf somatik yang membawa keterangan letak dengan tepat, sehingga nyerinya BERPINDAH — menjadi tajam, menetap, dan dapat ditunjuk dengan satu jari di titik McBurney. Perpindahan inilah tanda tunggal paling bernilai dalam diagnosis. Bila dibiarkan 24-72 jam, dinding yang mati akan pecah: nyeri sesaat MEREDA karena tekanan lepas — jebakan klasik yang membuat pemeriksa mengira pasien membaik — lalu segera berubah menjadi nyeri seluruh perut dengan defans muskular, yaitu peritonitis. Letak apendiks menentukan tandanya: yang retrosekal menempel pada m. psoas sehingga menimbulkan psoas sign, yang di pelvis menempel pada m. obturator internus sehingga menimbulkan obturator sign dan nyeri saat colok dubur.',
