    patofisiologi: 'Pada BPH, pembesaran zona transisi prostat mempersempit uretra (komponen statis) sekaligus meningkatkan tonus otot polos leher buli lewat reseptor alfa-1 (komponen dinamis) — dan pembagian ini menjelaskan terapinya: penghambat alfa mengurus komponen dinamis dalam hitungan hari, penghambat 5-alfa-reduktase mengurus komponen statis dalam hitungan bulan. Detrusor mula-mula mengompensasi dengan menebal dan berkontraksi lebih kuat, membentuk trabekulasi dan sakulasi; urin yang tertahan di dalam sakulasi mengendap dan membentuk BATU BULI, yang lalu menyumbat leher buli sehingga obstruksinya bertambah. Ketika detrusor akhirnya kelelahan atau tekanan dari luar meningkat mendadak, terjadi retensi. Yang harus diantisipasi setelah dekompresi adalah DIURESIS PASCAOBSTRUKSI: tubulus ginjal yang lama bekerja melawan tekanan balik kehilangan kemampuan memekatkan urin dan ureum yang tertimbun menarik air secara osmotik, sehingga produksi urin dapat melebihi 200 mL/jam berjam-jam dan pasien jatuh hipovolemik bila tidak dipantau. Hematuria ex vakuo terjadi bila buli yang sangat teregang dikosongkan terlalu cepat sehingga pembuluh submukosa yang tertekan mendadak terbuka.',
