      'Tes nitrazin: kertas berubah dari kuning menjadi BIRU karena air ketuban bersifat basa (pH 7,1-7,3) sedangkan sekret vagina asam (pH 4,5-6). Positif palsu oleh darah, air mani, antiseptik, dan vaginosis bakterial',
