      'Penyakit radang panggul — nyeri perut bawah, nyeri goyang porsio, demam; merupakan KOMPLIKASI yang harus dikenali, bukan sekadar pembanding',
      'Infeksi saluran kemih — disuria tanpa duh tubuh',
      'Uretritis akibat iritasi kimia (sabun, spermisida)',
