    patofisiologi: 'Rongga rahim setelah persalinan adalah tempat yang hampir dirancang untuk infeksi, dan menyadari hal itu menjelaskan seluruh pencegahannya. Bekas pelekatan plasenta merupakan luka terbuka seluas telapak tangan yang permukaannya kaya pembuluh darah dan tertutup bekuan serta jaringan mati (desidua nekrotik) — dengan kata lain, sebuah luka besar berisi media biakan yang sempurna. Pada saat yang sama serviks masih terbuka sehingga penghalang mekanis terhadap flora vagina hilang, dan lokia yang tergenang menjadi tempat kuman berkembang biak. Flora vagina yang biasanya tidak berbahaya — campuran aerob dan anaerob — naik melewati serviks yang terbuka dan menempati desidua itu. Pada persalinan pervaginam yang bersih, kontraksi rahim mengeluarkan isinya dan lapisan basal desidua beregenerasi sehingga kuman tersapu keluar; pada bedah sesar keadaannya berbeda, sebab ada jaringan yang terpotong dan dijahit, ada benang asing, dan ada jaringan yang mati akibat penjepitan — semuanya menurunkan jumlah kuman yang diperlukan untuk menimbulkan infeksi, dan itulah sebab risikonya berlipat ganda serta sebab antibiotik profilaksis sebelum insisi terbukti menurunkan kejadiannya. Bila infeksi tidak dihentikan, ia menyebar mengikuti bidang anatomi: ke miometrium menjadi endomiometritis, ke parametrium, lalu ke rongga peritoneum menjadi peritonitis pelvik. Yang paling berbahaya adalah penyebaran lewat pembuluh vena panggul yang saat nifas melebar dan alirannya lambat: terbentuk TROMBOFLEBITIS VENA PELVIK SEPTIK, yang melepaskan gumpalan berkuman ke paru dan tampil sebagai demam yang tetap tinggi walaupun antibiotik sudah tepat — satu-satunya petunjuk bahwa penyebabnya bukan kegagalan antibiotik melainkan bekuan yang menyimpan kuman di dalamnya. Sisa jaringan plasenta bekerja dengan cara lain lagi: selain menjadi media biakan, ia menghalangi rahim berkontraksi penuh, sehingga infeksi dan perdarahan berjalan bersamaan dan tidak satu pun akan sembuh sebelum sisanya dikeluarkan.',
