  'Hyperosmolar Hyperglycemic State (HHS/HONK) — resusitasi cairan': {
    definisi: 'Kegawatan hiperglikemia dengan gula darah sangat tinggi, osmolaritas serum efektif >320 mOsm/kg, dan dehidrasi berat, TANPA ketoasidosis bermakna; angka kematiannya jauh lebih tinggi daripada KAD.',
    etiologi: [
      'Umumnya pada DM tipe 2 usia lanjut, sering sebagai pengungkapan diabetes yang belum pernah terdiagnosis',
      'INFEKSI adalah pencetus tersering: pneumonia, infeksi saluran kemih, sepsis, ulkus kaki diabetik',
      'Peristiwa kardiovaskular akut: infark miokard, stroke — keduanya juga dapat menjadi AKIBAT, sehingga wajib dicari dua arah',
      'Obat: kortikosteroid, diuretik tiazid, antipsikotik atipikal, fenitoin, penghambat SGLT-2 (dapat menimbulkan bentuk campuran)',
      'Tidak minum obat diabetes atau insulin',
      'AKSES MINUM YANG TERBATAS — penentu yang paling menentukan: pasien yang tidak dapat minum sendiri (demensia, stroke, tinggal sendiri, terbaring) tidak dapat mengimbangi kehilangan cairan lewat kencing',
      'Pankreatitis akut, luka bakar, dialisis, dan nutrisi parenteral',
    ],
    patofisiologi: 'HHS dan KAD berasal dari kekurangan insulin yang sama, tetapi berbeda pada SATU HAL yang menentukan seluruh gambarannya: pada HHS masih tersisa sedikit insulin. Jumlah yang tersisa itu terlalu kecil untuk memasukkan glukosa ke otot dan lemak, sehingga gula darah tetap naik tanpa kendali — tetapi CUKUP untuk menekan lipolisis di jaringan lemak. Karena lipolisis tertekan, asam lemak bebas tidak dialirkan ke hati, badan keton tidak terbentuk dalam jumlah bermakna, dan asidosis tidak terjadi. Justru di situlah bahayanya: tanpa napas Kussmaul, tanpa bau aseton, dan tanpa nyeri perut, tidak ada gejala mencolok yang memaksa pasien datang lebih awal. Penyakit berjalan diam-diam selama berhari-hari sampai berminggu-minggu, dan selama itu gula darah dapat mencapai 600-1200 mg/dL. Glukosa yang melampaui ambang ginjal sekitar 180 mg/dL menarik air bersamanya keluar sebagai DIURESIS OSMOTIK; kehilangan cairan mencapai 8-12 liter, jauh melebihi KAD yang berkisar 6 liter. Pada orang muda, rasa haus akan mengimbanginya — tetapi pada lansia rasa haus memang menumpul, dan bila ditambah demensia atau stroke yang membuatnya tidak dapat mengambil minum sendiri, lingkaran itu tidak pernah terputus: makin dehidrasi, makin turun aliran darah ginjal, makin sedikit glukosa dapat dibuang, makin tinggi gula darah, makin banyak air ditarik keluar. Osmolaritas yang meninggi menarik air KELUAR DARI SEL OTAK, dan penyusutan sel otak itulah — bukan gulanya sendiri — yang menimbulkan penurunan kesadaran sampai koma; karena itu derajat kesadaran pada HHS berhubungan dengan OSMOLARITAS, bukan dengan kadar gula. Dari sini pula muncul bahaya terbesar dalam pengobatannya: sel otak yang menyusut perlahan membentuk zat terlarut penyeimbang di dalamnya untuk bertahan hidup, dan bila osmolaritas darah diturunkan terlalu cepat, air membanjir masuk ke sel yang masih penuh zat itu sehingga terjadi EDEMA SEREBRI. Itulah sebabnya koreksi HHS harus lambat dan bertahap, tidak boleh cepat.',
    penunjang: [
      'Gula darah sewaktu — umumnya >600 mg/dL, dapat melampaui 1000 mg/dL',
      'OSMOLARITAS SERUM EFEKTIF = 2 x Na (mEq/L) + glukosa (mg/dL)/18; nilai >320 mOsm/kg menegakkan diagnosis. Ureum TIDAK diikutkan karena menembus membran sel dan tidak menarik air',
      'NATRIUM TERKOREKSI = Na terukur + 1,6 (atau 2,4) x [(glukosa - 100)/100]. Natrium yang tampak rendah pada HHS umumnya PSEUDOHIPONATREMIA akibat glukosa yang menarik air ke dalam pembuluh — mengoreksinya sebagai hiponatremia sejati adalah kekeliruan yang berbahaya',
      'Analisis gas darah: pH >7,30 dan bikarbonat >18 mEq/L — inilah yang memisahkannya dari KAD',
      'Keton darah (beta-hidroksibutirat) atau keton urin: negatif sampai sedikit',
      'Elektrolit lengkap: kalium, natrium, klorida, fosfat, magnesium. KALIUM TOTAL TUBUH SELALU BERKURANG walaupun kadar darahnya tampak normal atau tinggi',
      'Ureum dan kreatinin (gagal ginjal prarenal), darah lengkap, CRP, prokalsitonin',
      'CARI PENCETUSNYA: urinalisis dan kultur urin, foto toraks, kultur darah, EKG dan troponin, dan CT kepala bila ada defisit neurologis fokal',
      'Anion gap, kreatin kinase (rabdomiolisis sering menyertai), dan HbA1c',
    ],
    diagnosisBanding: [
      'KETOASIDOSIS DIABETIK — lebih muda, DM tipe 1, awitan jam bukan hari, napas Kussmaul, bau aseton, nyeri perut, pH <7,3 dan keton positif kuat. Bentuk CAMPURAN keduanya sering terjadi',
      'Asidosis laktat — syok, sepsis, metformin pada gagal ginjal; laktat tinggi tanpa keton',
      'Ketoasidosis alkoholik — riwayat minum berat lalu berhenti dan tidak makan; gula darah normal atau rendah',
      'Hiponatremia atau hipernatremia dengan sebab lain; diabetes insipidus',
      'Sepsis dengan ensefalopati — dapat berdiri sendiri atau justru menjadi PENCETUS HHS',
      'Stroke dan perdarahan intrakranial — penurunan kesadaran dengan defisit fokal; dapat menjadi pencetus sekaligus akibat',
      'Uremia, gagal hati dengan ensefalopati, dan keracunan obat',
    ],
    anamnesis: [
      'Biasanya pasien DM tipe 2 usia lanjut, onset gejala lebih lambat (hari) dibanding KAD',
      'Poliuria, polidipsia, penurunan kesadaran bertahap hingga koma',
      'Faktor pencetus: infeksi, stroke, infark miokard, dehidrasi berat, obat (steroid, diuretik)',
      'Tanpa gejala Kussmaul/bau aseton (keton minimal/negatif)',
    ],
    pemeriksaanFisik: [
      'Dehidrasi berat, hipotensi, takikardia',
      'Penurunan kesadaran (GCS rendah, bisa stupor/koma)',
      'Tidak ada pernapasan Kussmaul (berbeda dengan KAD)',
      'Cari tanda infeksi/fokus infeksi sebagai pencetus',
    ],
    kriteriaDiagnosis:
      'GDS sangat tinggi (>600 mg/dL), osmolaritas serum efektif >320 mOsm/kg, pH >7,3, bikarbonat >18 mEq/L, keton minimal/negatif.',
    tatalaksana: [
      'Resusitasi cairan agresif: NaCl 0,9% 15-20 mL/kgBB jam pertama, koreksi defisit cairan total (bisa 8-10L) secara bertahap dalam 24-48 jam',
      'Insulin regular IV kontinu 0,1 unit/kgBB/jam setelah resusitasi cairan awal dan kalium adekuat',
      'Koreksi kalium seperti pada KAD',
      'Monitor status neurologis dan osmolaritas serial — koreksi terlalu cepat berisiko edema serebri',
      'Cari dan atasi faktor pencetus',
    ],
    tips: 'Mortalitas HHS lebih tinggi dari KAD karena populasi lanjut usia dan derajat dehidrasi lebih berat — resusitasi cairan adalah kunci utama, bukan insulin.',
  },

