      'Pseudogout (CPPD) — lutut dan pergelangan tangan, kondrokalsinosis pada foto',
      'Bursitis dan tendinitis — nyeri DI LUAR garis sendi, gerak pasif tidak nyeri',
      'Nyeri alih dari panggul ke lutut — periksa panggulnya pada nyeri lutut yang tidak khas',
